# -*- coding: utf-8 -*-
"""Electrical symbol library data (editable). GPL-3.0-or-later.

HONEST SCOPE: every shape below is an ORIGINAL illustrative drawing built from lines, circles and arcs, in the
general spirit of common schematic conventions. They are NOT copies of IEC 60617, ANSI/IEEE 315 or manufacturer
drawings and are not certified symbols. Terminal designations follow the markings documented by ABB for
contactors, auxiliary contacts and overload relays (main poles 1L1/3L2/5L3 to 2T1/4T2/6T3, coil A1/A2,
auxiliary NO 13-14, NC 21-22, overload NC 95-96 and NO 97-98), source: ABB Low Voltage Products catalogue,
section "Terminal Marking and Positioning" (IEC 60445, IEC 60947-1, EN 50005, EN 50011, EN 50012 referenced
there), https://files.kempstoncontrols.com/files/6cc38b9721026dca8234783b3beacbbc/1SBN010010R1001.pdf
Always take real terminal numbers and ratings from the device nameplate and datasheet.

Format: KEY -> (arabic_label, terminals, primitives)
  primitive 'L': ('L', [(x,y), ...])           open polyline
  primitive 'C': ('C', cx, cy, r)              circle
  primitive 'A': ('A', cx, cy, r, a0_deg, a1_deg) arc, counter-clockwise from a0 to a1
Users can add symbols in a JSON file (see elec_lib.py, USER_FILE) with the same structure.
"""


def _rect(x0, y0, x1, y1):
    return ('L', [(x0, y0), (x1, y0), (x1, y1), (x0, y1), (x0, y0)])


def _contact_no(x, y0=-20, y1=20):
    """vertical normally-open contact: lead, gap, blade"""
    return [('L', [(x, y0), (x, y0 + 10)]), ('L', [(x, y0 + 10), (x + 10, y1 - 12)]), ('L', [(x, y1 - 8), (x, y1)])]


def _contact_nc(x, y0=-20, y1=20):
    return _contact_no(x, y0, y1) + [('L', [(x - 4, y1 - 12), (x + 14, y1 - 12)])]


